begin;
select plan(16);
select ok(not has_function_privilege('anon','public.create_band(text,text,text)','EXECUTE'),'anon cannot execute retired create_band(text,text,text)');
select ok(not has_function_privilege('anon','public.create_invite(uuid)','EXECUTE'),'anon cannot execute retired create_invite(uuid)');
select ok(not has_function_privilege('anon','public.inspect_invite(text)','EXECUTE'),'anon cannot execute retired inspect_invite(text)');
select ok(not has_function_privilege('anon','public.redeem_invite(text,text)','EXECUTE'),'anon cannot execute retired redeem_invite(text,text)');
select ok(not has_function_privilege('authenticated','public.create_band(text,text,text)','EXECUTE'),'authenticated cannot execute retired create_band(text,text,text)');
select ok(not has_function_privilege('authenticated','public.create_invite(uuid)','EXECUTE'),'authenticated cannot execute retired create_invite(uuid)');
select ok(not has_function_privilege('authenticated','public.inspect_invite(text)','EXECUTE'),'authenticated cannot execute retired inspect_invite(text)');
select ok(not has_function_privilege('authenticated','public.redeem_invite(text,text)','EXECUTE'),'authenticated cannot execute retired redeem_invite(text,text)');
select ok(not has_table_privilege('authenticated','public.band_invites','SELECT'),'retired invite rows cannot be queried by app users');
select ok(not has_table_privilege('anon','public.band_invites','SELECT'),'retired invite rows are not public');
select ok(has_function_privilege('authenticated','public.create_code_band(text,text,text,text,text,text)','EXECUTE'),'band-code RPC create_code_band(text,text,text,text,text,text) remains enabled');
select ok(has_function_privilege('authenticated','public.begin_band_access(text,text)','EXECUTE'),'band-code RPC begin_band_access(text,text) remains enabled');
select ok(has_function_privilege('authenticated','public.member_pin_login(uuid,text)','EXECUTE'),'band-code RPC member_pin_login(uuid,text) remains enabled');
select ok(has_function_privilege('authenticated','public.register_band_profile(text,text,text)','EXECUTE'),'band-code RPC register_band_profile(text,text,text) remains enabled');
set local role authenticated;
select throws_ok($$select public.create_invite('00000000-0000-0000-0000-000000000000')$$,'42501',null,'direct legacy invite call is denied');
reset role;
set local role anon;
select throws_ok($$select public.inspect_invite('old-token')$$,'42501',null,'unauthenticated token inspection is denied');
select * from finish();
rollback;
